// ── Container launch ─────────────────────────────────────────────────────────

func TestExposedPortsAreReturnedAgainstTheImageTheyCameFrom(t *testing.T) {
	installFakeDocker(t, fakeScript{
		"docker image inspect": {Stdout: `{"80/tcp":{},"443/tcp":{}}`},
	})

