140	func (b *RegistryBrowser) viewTags() string {
141		displayed := b.filteredSortedMultiTags()
142		if len(displayed) == 0 {
143			if b.pendingSearches > 0 {
144				return theme.EmptyLineBg(b.width) + "\n" +
145					theme.SpinnerMessage(b.spinner.View(), "Searching registries...")
146			}
147			return theme.DimStyle.Render("  No tags found")
148		}
149		return b.tagTable.View()
150	}
