1	package config
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"regexp"
8		"strings"
9	
10		"gopkg.in/yaml.v3"
11	)
12	
13	// Config représente la configuration complète de l'application
14	type Config struct {
15		App      AppConfig      `yaml:"app"`
16		Status   StatusConfig   `yaml:"status"`
17		GitLab   GitLabConfig   `yaml:"gitlab"`
18		Registry RegistryConfig `yaml:"registry"`
19		Scan     ScanConfig     `yaml:"scan"`
20		Docker   DockerConfig   `yaml:"docker"`
21	}
22	
23	// DockerConfig contient les paramètres Docker de l'application
24	type DockerConfig struct {
25		// NetworkToolImage is the Docker image used for network connectivity tests.
26		// It must include ping, curl, and nc (netcat) binaries.
27		NetworkToolImage string `yaml:"network_tool_image"`
28	}
29	
30	// AppConfig contient les paramètres globaux de l'app
31	type AppConfig struct {
32		Theme           string `yaml:"theme"`
33		LogFile         string `yaml:"log_file"`
34		DefaultView     string `yaml:"default_view"`
35		WorkspacesDir   string `yaml:"workspaces_dir"`
36		IDECommand      string `yaml:"ide_command"`
37		TerminalCommand string `yaml:"terminal_command"` // e.g. "kitty --directory" — empty = auto-detect
38	
39		// SecretBackend pins where secrets are stored: "auto" (default), "keyring"
40		// for the host secret manager only, or "git-credential" for git's helper.
41		// See credentials.Select for what each one resolves to.
42		SecretBackend string `yaml:"secret_backend"`
43	}
44	
45	// GitLabConfig contient la configuration GitLab
46	//
47	// Le token n'est pas ici : il vit dans le gestionnaire de secrets de l'hôte
48	// (§3.9). Un `token:` laissé par une version antérieure est déplacé dans le
49	// store puis retiré du fichier — voir secrets.go.
50	type GitLabConfig struct {
51		URL                string           `yaml:"url"`
52		DefaultParentGroup string           `yaml:"default_parent_group"`
53		DefaultVisibility  string           `yaml:"default_visibility"`
54		CloneMethod        string           `yaml:"clone_method"`
55		Pull               GitLabPullConfig `yaml:"pull"`
56	}
57	
58	// GitLabPullConfig contient la configuration pour la synchronisation
59	type GitLabPullConfig struct {
60		TargetDir       string `yaml:"target_dir"`
61		ParallelJobs    int    `yaml:"parallel_jobs"`
62		MaxDepth        int    `yaml:"max_depth"`
63		IncludeArchived bool   `yaml:"include_archived"`
64	}
65	
66	// RegistryItem represents a single Docker/OCI registry with optional alias support.
67	// The password is NOT stored here; it is persisted via `docker login` / system credential helper.
68	type RegistryItem struct {
69		URL         string `yaml:"url"`
70		Username    string `yaml:"username"`
71		Alias       string `yaml:"alias"`
72		AuthEnabled bool   `yaml:"auth_enabled"`
73		// ManagementURL is optional. Set it when the Docker registry URL differs from the
74		// URL used by the repository manager's API (e.g. Nexus connector subdomains,
75		// Artifactory virtual repos). The group member discovery uses this URL instead of
76		// the registry URL. Example: "https://nexus.example.com/repository/docker-group".
77		ManagementURL string `yaml:"management_url,omitempty"`
78	}
79	
80	// RegistryConfig contient la configuration du registre OCI
81	//
82	// Comme pour GitLabConfig, le mot de passe n'est pas ici (§3.9).
83	type RegistryConfig struct {
84		URL                 string         `yaml:"url,omitempty"`
85		Username            string         `yaml:"username,omitempty"`
86		TemplatesRepository string         `yaml:"templates_repository"`
87		CacheDir            string         `yaml:"cache_dir"`
88		Registries          []RegistryItem `yaml:"registries,omitempty"`
89	}
90	
91	// ScanConfig contient la configuration pour les scans de sécurité
92	type ScanConfig struct {
93		TrivyPath          string `yaml:"trivy_path"`           // Chemin custom vers trivy (optionnel)
94		TrivyImage         string `yaml:"trivy_image"`          // Image Docker trivy (défaut: aquasec/trivy)
95		TrivyServer        string `yaml:"trivy_server"`         // URL du serveur Trivy (optionnel, mode client-serveur)
96		GitleaksPath       string `yaml:"gitleaks_path"`        // Chemin custom vers gitleaks (optionnel)
97		GitleaksImage      string `yaml:"gitleaks_image"`       // Image Docker gitleaks (défaut: zricethezav/gitleaks)
98		CacheDir           string `yaml:"cache_dir"`            // Cache des rapports
99		SBOMOutputDir      string `yaml:"sbom_output_dir"`      // Répertoire de sortie SBOM (optionnel, défaut: à côté de la cible)
100		MaxCachedReports   int    `yaml:"max_cached_reports"`   // Nombre max de rapports conservés
101		Timeout            int    `yaml:"timeout"`              // Timeout en secondes
102		MaxConcurrentScans int    `yaml:"max_concurrent_scans"` // Nombre max de scans parallèles
103	
104		// Scan options (persistées depuis la vue security)
105		EnableVuln      bool   `yaml:"enable_vuln"`
106		EnableSecret    bool   `yaml:"enable_secret"`
107		EnableMisconfig bool   `yaml:"enable_misconfig"`
108		EnableLicense   bool   `yaml:"enable_license"`
109		GenerateSBOM    bool   `yaml:"generate_sbom"`
110		IgnoreUnfixed   bool   `yaml:"ignore_unfixed"`
111		IgnoreEOL       bool   `yaml:"ignore_eol"`
112		GitleaksHistory bool   `yaml:"gitleaks_history"`
113		GitleaksConfig  string `yaml:"gitleaks_config"`
114	}
115	
116	// StatusConfig contient la configuration pour le monitoring
117	type StatusConfig struct {
118		RefreshInterval int               `yaml:"refresh_interval"`
119		Timeout         int               `yaml:"timeout"` // in seconds
120		AutoRefresh     bool              `yaml:"auto_refresh"`
121		Components      []ComponentConfig `yaml:"components"`
122	}
123	
124	// ComponentConfig représente un composant à monitorer
125	type ComponentConfig struct {
126		Name    string `yaml:"name"`
127		Type    string `yaml:"type"`              // http, https, icmp, dns
128		Target  string `yaml:"target"`            // URL, IP, ou hostname
129		Timeout int    `yaml:"timeout,omitempty"` // En secondes
130	
131		// Legacy support
132		URL string `yaml:"url,omitempty"` // Deprecated, use Target
133	
134		// ICMP specific
135		Count int `yaml:"count,omitempty"` // Nombre de pings
136	
137		// DNS specific
138		Nameserver string `yaml:"nameserver,omitempty"` // Serveur DNS custom
139	}
140	
141	// Load charge la configuration depuis le contexte actuel
142	func Load() (*Config, error) {
143		ctx, err := GetCurrentContext()
144		if err != nil {
145			// Fallback to default on error
146			ctx = "default"
147		}
148	
149		cfg, err := LoadContext(ctx)
150		if err != nil {
151			// Si le fichier n'existe pas, retourner config par défaut
152			if os.IsNotExist(err) || strings.Contains(err.Error(), "does not exist") {
153				return Default(), nil
154			}
155			// Sinon (parsing error, permission error, etc.), propager l'erreur
156			return nil, err
157		}
158	
159		return cfg, nil
160	}
161	
162	// applyDefaults applique les valeurs par défaut à une configuration
163	func applyDefaults(cfg *Config) {
164		homeDir, _ := os.UserHomeDir()
165	
166		if cfg.App.Theme == "" {
167			cfg.App.Theme = "dark"
168		}
169		if cfg.App.LogFile == "" {
170			cfg.App.LogFile = filepath.Join(homeDir, ".devdesk", "devdesk.log")
171		}
172		if cfg.App.DefaultView == "" {
173			cfg.App.DefaultView = "dashboard"
174		}
175		if cfg.App.WorkspacesDir == "" {
176			cfg.App.WorkspacesDir = filepath.Join(homeDir, "workspaces")
177		}
178		if cfg.App.IDECommand == "" {
179			cfg.App.IDECommand = "code"
180		}
181		if cfg.Status.RefreshInterval == 0 {
182			cfg.Status.RefreshInterval = 10
183		}
184		if cfg.Status.Timeout == 0 {
185			cfg.Status.Timeout = 5
186		}
187		if cfg.GitLab.DefaultVisibility == "" {
188			cfg.GitLab.DefaultVisibility = "private"
189		}
190		if cfg.GitLab.CloneMethod == "" {
191			cfg.GitLab.CloneMethod = "https"
192		}
193		if cfg.GitLab.Pull.ParallelJobs == 0 {
194			cfg.GitLab.Pull.ParallelJobs = 4
195		}
196		if cfg.GitLab.Pull.MaxDepth == 0 {
197			cfg.GitLab.Pull.MaxDepth = 5
198		}
199		if cfg.GitLab.Pull.TargetDir == "" {
200			cfg.GitLab.Pull.TargetDir = filepath.Join(homeDir, "workspace")
201		}
202		if cfg.Registry.CacheDir == "" {
203			cfg.Registry.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "templates")
204		}
205		// Migrate old single-registry config to the new Registries list
206		if cfg.Registry.URL != "" && len(cfg.Registry.Registries) == 0 {
207			cfg.Registry.Registries = []RegistryItem{{
208				URL:         cfg.Registry.URL,
209				Username:    cfg.Registry.Username,
210				AuthEnabled: cfg.Registry.URL != "",
211			}}
212		}
213		if cfg.Scan.CacheDir == "" {
214			cfg.Scan.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "scans")
215		}
216		if cfg.Scan.MaxCachedReports == 0 {
217			cfg.Scan.MaxCachedReports = 50
218		}
219		if cfg.Scan.Timeout == 0 {
220			cfg.Scan.Timeout = 300
221		}
222		if cfg.Scan.MaxConcurrentScans == 0 {
223			cfg.Scan.MaxConcurrentScans = 3
224		}
225	
226		if cfg.Docker.NetworkToolImage == "" {
227			cfg.Docker.NetworkToolImage = "nicolaka/netshoot"
228		}
229	
230		// Backward compat: configs created before the scan-option booleans were introduced
231		// will have all of them at Go's zero value (false). Treat "all disabled" as
232		// "never configured" and apply sensible defaults so scans work out of the box.
233		if !cfg.Scan.EnableVuln && !cfg.Scan.EnableSecret && !cfg.Scan.EnableMisconfig && !cfg.Scan.EnableLicense {
234			cfg.Scan.EnableVuln = true
235			cfg.Scan.EnableSecret = true
236		}
237	}
238	
239	// Default retourne la configuration par défaut
240	func Default() *Config {
241		homeDir, _ := os.UserHomeDir()
242		return &Config{
243			App: AppConfig{
244				Theme:         "dark",
245				LogFile:       filepath.Join(homeDir, ".devdesk", "devdesk.log"),
246				DefaultView:   "dashboard",
247				WorkspacesDir: filepath.Join(homeDir, "workspaces"),
248				IDECommand:    "code",
249			},
250			Status: StatusConfig{
251				RefreshInterval: 10,
252				AutoRefresh:     true,
253				Timeout:         5,
254				Components:      []ComponentConfig{},
255			},
256			GitLab: GitLabConfig{
257				DefaultVisibility: "private",
258				CloneMethod:       "https",
259				Pull: GitLabPullConfig{
260					TargetDir:       filepath.Join(homeDir, "workspace"),
261					ParallelJobs:    4,
262					MaxDepth:        5,
263					IncludeArchived: false,
264				},
265			},
266			Registry: RegistryConfig{
267				CacheDir: filepath.Join(homeDir, ".devdesk", "cache", "templates"),
268			},
269			Scan: ScanConfig{
270				TrivyPath:          "", // Auto-detect in PATH
271				GitleaksPath:       "", // Auto-detect in PATH
272				CacheDir:           filepath.Join(homeDir, ".devdesk", "cache", "scans"),
273				MaxCachedReports:   50,
274				Timeout:            300, // 5 minutes
275				MaxConcurrentScans: 3,
276				EnableVuln:         true,
277				EnableSecret:       true,
278			},
279			Docker: DockerConfig{
280				NetworkToolImage: "nicolaka/netshoot",
281			},
282		}
283	}
284	
285	// ConfigDir retourne le répertoire de configuration
286	func ConfigDir() (string, error) {
287		homeDir, err := os.UserHomeDir()
288		if err != nil {
289			return "", err
290		}
291		return filepath.Join(homeDir, ".devdesk"), nil
292	}
293	
294	// EnsureConfigDir crée le répertoire de configuration s'il n'existe pas
295	func EnsureConfigDir() error {
296		dir, err := ConfigDir()
297		if err != nil {
298			return err
299		}
300	
301		return os.MkdirAll(dir, 0755)
302	}
303	
304	// Save sauvegarde la configuration dans le fichier du contexte actuel
305	func Save(cfg *Config) error {
306		ctx, err := GetCurrentContext()
307		if err != nil {
308			// Fallback to default on error
309			ctx = "default"
310		}
311	
312		return SaveContext(cfg, ctx)
313	}
314	
315	// Context Management Functions
316	
317	// GetCurrentContext lit le nom du contexte actuel depuis .current-context
318	// Retourne "default" si le fichier n'existe pas ou est vide
319	func GetCurrentContext() (string, error) {
320		homeDir, err := os.UserHomeDir()
321		if err != nil {
322			return "", err
323		}
324	
325		contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")
326	
327		// Si le fichier n'existe pas, retourner "default"
328		if _, err := os.Stat(contextFile); os.IsNotExist(err) {
329			return "default", nil
330		}
331	
332		data, err := os.ReadFile(contextFile)
333		if err != nil {
334			return "", err
335		}
336	
337		context := strings.TrimSpace(string(data))
338		if context == "" {
339			return "default", nil
340		}
341	
342		return context, nil
343	}
344	
345	// SetCurrentContext écrit le nom du contexte dans .current-context
346	func SetCurrentContext(name string) error {
347		if err := ValidateContextName(name); err != nil {
348			return err
349		}
350	
351		homeDir, err := os.UserHomeDir()
352		if err != nil {
353			return err
354		}
355	
356		contextFile := filepath.Join(homeDir, ".devdesk", ".current-context")
357	
358		// Assurer que le répertoire existe
359		if err := EnsureConfigDir(); err != nil {
360			return err
361		}
362	
363		return os.WriteFile(contextFile, []byte(name), 0600)
364	}
365	
366	// ListContexts découvre les contextes disponibles en listant les fichiers config-*.yaml
367	// Retourne une slice de noms de contextes (sans préfixe "config-" ni suffixe ".yaml")
368	// Inclut toujours "default" si config.yaml existe
369	func ListContexts() ([]string, error) {
370		homeDir, err := os.UserHomeDir()
371		if err != nil {
372			return nil, err
373		}
374	
375		configDir := filepath.Join(homeDir, ".devdesk")
376		contexts := []string{}
377	
378		// Vérifier le contexte default
379		defaultPath := filepath.Join(configDir, "config.yaml")
380		if _, err := os.Stat(defaultPath); err == nil {
381			contexts = append(contexts, "default")
382		}
383	
384		// Glob pour les contextes nommés
385		pattern := filepath.Join(configDir, "config-*.yaml")
386		matches, err := filepath.Glob(pattern)
387		if err != nil {
388			return nil, err
389		}
390	
391		for _, match := range matches {
392			// Extraire le nom: config-{name}.yaml → {name}
393			basename := filepath.Base(match)
394			name := strings.TrimPrefix(basename, "config-")
395			name = strings.TrimSuffix(name, ".yaml")
396			contexts = append(contexts, name)
397		}
398	
399		return contexts, nil
400	}
401	
402	// LoadContext charge la configuration pour un contexte spécifique
403	// contextName = "default" → config.yaml
404	// contextName = "dev" → config-dev.yaml
405	func LoadContext(contextName string) (*Config, error) {
406		if err := ValidateContextName(contextName); err != nil {
407			return nil, err
408		}
409	
410		configPath, err := GetContextPath(contextName)
411		if err != nil {
412			return nil, err
413		}
414	
415		// Vérifier si le fichier existe
416		if _, err := os.Stat(configPath); os.IsNotExist(err) {
417			return nil, fmt.Errorf("context '%s' does not exist (no file at %s)", contextName, configPath)
418		}
419	
420		// Lire et parser YAML
421		data, err := os.ReadFile(configPath)
422		if err != nil {
423			return nil, err
424		}
425	
426		var cfg Config
427		if err := yaml.Unmarshal(data, &cfg); err != nil {
428			return nil, fmt.Errorf("failed to parse context '%s': %w", contextName, err)
429		}
430	
431		// Appliquer les valeurs par défaut
432		applyDefaults(&cfg)
433	
434		// Étendre les chemins (tildes)
435		if home, err := os.UserHomeDir(); err == nil {
436			cfg.ExpandPaths(home)
437		}
438	
439		return &cfg, nil
440	}
441	
442	// ExpandPaths étend les tildes (~) dans les chemins de configuration
443	func (c *Config) ExpandPaths(homeDir string) {
444		expand := func(path string) string {
445			if strings.HasPrefix(path, "~/") {
446				return filepath.Join(homeDir, path[2:])
447			}
448			return path
449		}
450	
451		c.App.LogFile = expand(c.App.LogFile)
452		c.App.WorkspacesDir = expand(c.App.WorkspacesDir)
453		c.GitLab.Pull.TargetDir = expand(c.GitLab.Pull.TargetDir)
454		c.Registry.CacheDir = expand(c.Registry.CacheDir)
455		c.Scan.CacheDir = expand(c.Scan.CacheDir)
456		c.Scan.SBOMOutputDir = expand(c.Scan.SBOMOutputDir)
457		c.Scan.TrivyPath = expand(c.Scan.TrivyPath)
458		c.Scan.GitleaksPath = expand(c.Scan.GitleaksPath)
459		c.Scan.GitleaksConfig = expand(c.Scan.GitleaksConfig)
460	}
461	
462	// SaveContext sauvegarde la configuration dans un fichier de contexte spécifique
463	func SaveContext(cfg *Config, contextName string) error {
464		if err := ValidateContextName(contextName); err != nil {
465			return err
466		}
467	
468		configPath, err := GetContextPath(contextName)
469		if err != nil {
470			return err
471		}
472	
473		// Assurer que le répertoire existe
474		if err := EnsureConfigDir(); err != nil {
475			return err
476		}
477	
478		// Marshaller en YAML
479		data, err := yaml.Marshal(cfg)
480		if err != nil {
481			return err
482		}
483	
484		// Écrire le fichier
485		return os.WriteFile(configPath, data, 0600)
486	}
487	
488	// ContextExists vérifie si un fichier de configuration de contexte existe
489	func ContextExists(contextName string) (bool, error) {
490		if err := ValidateContextName(contextName); err != nil {
491			return false, err
492		}
493	
494		configPath, err := GetContextPath(contextName)
495		if err != nil {
496			return false, err
497		}
498	
499		_, err = os.Stat(configPath)
500		if os.IsNotExist(err) {
501			return false, nil
502		}
503		if err != nil {
504			return false, err
505		}
506	
507		return true, nil
508	}
509	
510	// GetContextPath retourne le chemin du fichier pour un contexte
511	// "default" → ~/.devdesk/config.yaml
512	// "dev" → ~/.devdesk/config-dev.yaml
513	func GetContextPath(contextName string) (string, error) {
514		homeDir, err := os.UserHomeDir()
515		if err != nil {
516			return "", err
517		}
518	
519		configDir := filepath.Join(homeDir, ".devdesk")
520	
521		var filename string
522		if contextName == "default" {
523			filename = "config.yaml"
524		} else {
525			filename = fmt.Sprintf("config-%s.yaml", contextName)
526		}
527	
528		return filepath.Join(configDir, filename), nil
529	}
530	
531	// ValidateContextName valide le format du nom de contexte
532	// Doit être "default" ou correspondre à ^[a-z0-9-]+$
533	func ValidateContextName(name string) error {
534		if name == "default" {
535			return nil
536		}
537	
538		// Pattern: lettres minuscules, chiffres, tirets
539		matched, err := regexp.MatchString("^[a-z0-9-]+$", name)
540		if err != nil {
541			return err
542		}
543	
544		if !matched {
545			return fmt.Errorf("invalid context name '%s': must contain only lowercase letters, numbers, and hyphens", name)
546		}
547	
548		return nil
549	}
550	
551	// CreateContext crée un nouveau contexte avec une configuration par défaut
552	// Monitors vides, GitLab URL vide, autres valeurs par défaut
553	func CreateContext(contextName string) error {
554		if err := ValidateContextName(contextName); err != nil {
555			return err
556		}
557	
558		// Vérifier si existe déjà
559		exists, err := ContextExists(contextName)
560		if err != nil {
561			return err
562		}
563		if exists {
564			return fmt.Errorf("context '%s' already exists", contextName)
565		}
566	
567		// Créer config avec defaults
568		cfg := Default()
569	
570		// Vider monitors et GitLab pour nouveau contexte
571		cfg.Status.Components = []ComponentConfig{}
572		cfg.GitLab.URL = ""
573	
574		// Sauvegarder
575		return SaveContext(cfg, contextName)
576	}
