1	package cache
2	
3	import (
4		"crypto/sha256"
5		"encoding/json"
6		"fmt"
7		"log"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	
13		"github.com/anthnel/devdesk/internal/scan"
14	)
15	
16	// ImageScanEntry holds cached CVE counts for a scanned image
17	type ImageScanEntry struct {
18		ImageID   string    `json:"image_id"`
19		Critical  int       `json:"critical"`
20		High      int       `json:"high"`
21		Medium    int       `json:"medium"`
22		Low       int       `json:"low"`
23		ScannedAt time.Time `json:"scanned_at"`
24	}
25	
26	// ImageScanCache manages the image scan results cache file
27	type ImageScanCache struct {
28		mu      sync.RWMutex
29		path    string
30		entries map[string]ImageScanEntry // keyed by "repo:tag"
31	}
32	
33	// NewImageScanCache creates or loads the cache from ~/.devdesk/cache/image-scans.json
34	func NewImageScanCache() (*ImageScanCache, error) {
35		homeDir, err := os.UserHomeDir()
36		if err != nil {
37			return nil, err
38		}
39	
40		cacheDir := filepath.Join(homeDir, ".devdesk", "cache")
41		if err := os.MkdirAll(cacheDir, 0755); err != nil {
42			return nil, err
43		}
44	
45		c := &ImageScanCache{
46			path:    filepath.Join(cacheDir, "image-scans.json"),
47			entries: make(map[string]ImageScanEntry),
48		}
49	
50		c.load()
51		return c, nil
52	}
53	
54	// load reads the cache file from disk
55	func (c *ImageScanCache) load() {
56		data, err := os.ReadFile(c.path)
57		if err != nil {
58			return
59		}
60		if err := json.Unmarshal(data, &c.entries); err != nil {
61			log.Printf("ERROR [cache/image_scan] unmarshal cache file %s: %v", c.path, err)
62		}
63	}
64	
65	// save writes the cache to disk
66	func (c *ImageScanCache) save() error {
67		data, err := json.MarshalIndent(c.entries, "", "  ")
68		if err != nil {
69			return err
70		}
71		return os.WriteFile(c.path, data, 0600)
72	}
73	
74	// Get returns the cached scan entry for an image, or nil if not found
75	func (c *ImageScanCache) Get(imageKey string) *ImageScanEntry {
76		c.mu.RLock()
77		defer c.mu.RUnlock()
78		if entry, ok := c.entries[imageKey]; ok {
79			return &entry
80		}
81		return nil
82	}
83	
84	// Set stores a scan entry and persists to disk
85	func (c *ImageScanCache) Set(imageKey string, entry ImageScanEntry) error {
86		c.mu.Lock()
87		defer c.mu.Unlock()
88		c.entries[imageKey] = entry
89		return c.save()
90	}
91	
92	// GetAll returns all cached entries
93	func (c *ImageScanCache) GetAll() map[string]ImageScanEntry {
94		c.mu.RLock()
95		defer c.mu.RUnlock()
96		result := make(map[string]ImageScanEntry, len(c.entries))
97		for k, v := range c.entries {
98			result[k] = v
99		}
100		return result
101	}
102	
103	// Delete removes one entry from the cache and persists to disk
104	func (c *ImageScanCache) Delete(imageKey string) error {
105		c.mu.Lock()
106		defer c.mu.Unlock()
107		delete(c.entries, imageKey)
108		return c.save()
109	}
110	
111	// Reload re-reads the cache from disk
112	func (c *ImageScanCache) Reload() {
113		c.mu.Lock()
114		defer c.mu.Unlock()
115		c.load()
116	}
117	
118	// imageScanResultDir returns the directory for full image scan results, creating it if needed
119	func imageScanResultDir() (string, error) {
120		homeDir, err := os.UserHomeDir()
121		if err != nil {
122			return "", err
123		}
124		dir := filepath.Join(homeDir, ".devdesk", "cache", "image-results")
125		if err := os.MkdirAll(dir, 0755); err != nil {
126			return "", err
127		}
128		return dir, nil
129	}
130	
131	// imageResultFilePath returns the JSON file path for the full scan result of an image.
