59	// The browser needs somewhere to search, so it says what is missing rather than
60	// opening empty.
61	func TestBrowserNeedsARegistry(t *testing.T) {
62		cfg := testConfig()
63		cfg.Registry.Registries = nil
64		m := feed(t, New(cfg), tea.WindowSizeMsg{Width: 180, Height: 30}, ImagesListMsg{Images: imageFixtures()})
65	
66		m = feed(t, m, testutil.Key("b"))
67	
68		if m.registryBrowser != nil {
69			t.Error("the browser opened with no registries configured")
70		}
71		if !strings.Contains(m.errorMsg, "No registries") {
72			t.Errorf("errorMsg = %q, want it to name the missing configuration", m.errorMsg)
73		}
74	}
75	
76	// A registry may be a group fronting several members; the browser resolves that
77	// before showing the list, so the user picks real registries rather than one
78	// alias hiding four.
79	func TestBrowserResolvesGroupsBeforeShowingTheForm(t *testing.T) {
80		m := feed(t, loadedModel(t), testutil.Key("b"))
81	
82		if m.registryBrowser.state != browserStateResolving {
83			t.Errorf("the browser opened in state %d, want it resolving", m.registryBrowser.state)
84		}
85	
86		m = feed(t, m, RegistryGroupDetectedMsg{
87			RegistryURL: "registry.example.com",
88			Slug:        "prod",
89			Members: []registrymgr.GroupMember{
90				{Alias: "docker-hosted", URL: "registry.example.com/hosted"},
91				{Alias: "docker-proxy", URL: "registry.example.com/proxy"},
92			},
93		})
94	
95		if m.registryBrowser.state != browserStateInput {
96			t.Errorf("the browser is in state %d once every detection landed", m.registryBrowser.state)
97		}
98		// The group expanded into its two members, plus the plain registry.
99		if got := len(m.registryBrowser.entries); got != 3 {
100			t.Errorf("entries = %d, want the group's two members plus docker.io", got)
101		}
102	}
103	
104	// Only a group is waited for. A plain registry has nothing to discover, and
105	// before the provider was declared every one of them cost a round trip that
106	// could only come back saying so — which is the wait D13 is about.
107	func TestOnlyGroupsAreWaitedFor(t *testing.T) {
108		cfg := testConfig()
109		for i := range cfg.Registry.Registries {
110			cfg.Registry.Registries[i].Kind = config.KindRegistry
111		}
112		m := feed(t, New(cfg), tea.WindowSizeMsg{Width: 180, Height: 30}, ImagesListMsg{Images: imageFixtures()})
113	
114		m = feed(t, m, testutil.Key("b"))
115	
116		if m.registryBrowser.state != browserStateInput {
117			t.Errorf("the browser opened in state %d with no group configured, want the form straight away",
118				m.registryBrowser.state)
119		}
120		if got := len(m.registryBrowser.entries); got != 2 {
121			t.Errorf("entries = %d, want both registries offered as themselves", got)
122		}
123	}
124	
125	// A result for something that was never waited for must not be counted, or it
126	// finalizes the list a second time and drops what the user had unchecked.
127	func TestAStrayDetectionIsIgnored(t *testing.T) {
128		m := feed(t, loadedModel(t), testutil.Key("b"))
129		before := m.registryBrowser.pendingDetections
130	
131		m = feed(t, m, RegistryGroupDetectedMsg{RegistryURL: "docker.io", Slug: "hub"})
132	
133		if got := m.registryBrowser.pendingDetections; got != before {
134			t.Errorf("pendingDetections = %d after a result for a plain registry, want %d", got, before)
135		}
136		if m.registryBrowser.state != browserStateResolving {
