139	}
140	
141	// A detection that fails must not strand the browser on its spinner: the
142	// registry is offered as itself.
143	func TestBrowserSurvivesAFailedDetection(t *testing.T) {
144		m := feed(t, loadedModel(t), testutil.Key("b"))
145	
146		m = feed(t, m,
