1	package ociresources
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/bubbles/spinner"
7		tea "github.com/charmbracelet/bubbletea"
8	
9		"github.com/anthnel/devdesk/internal/config"
10		"github.com/anthnel/devdesk/internal/docker"
11	)
12	
13	// InEditMode returns true when a text input is active (blocks command mode).
14	func (b *RegistryBrowser) InEditMode() bool {
15		if b.state == browserStateResolving {
16			return false
17		}
18		if b.state == browserStateInput && b.focusedField == brFieldRepo {
19			return true
20		}
21		return b.state == browserStateTags && b.filterActive
22	}
23	
24	// IsSearching returns true while registry tag queries are still in flight.
25	func (b *RegistryBrowser) IsSearching() bool {
26		return b.pendingSearches > 0
27	}
28	
29	// Update handles all messages for the browser.
30	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
31		switch msg := msg.(type) {
32		case tea.KeyMsg:
33			return b.handleKeyMsg(msg)
34		case spinner.TickMsg:
35			if b.state == browserStateStatus || b.state == browserStateResolving || len(b.scanningTags) > 0 || b.pendingSearches > 0 {
36				var cmd tea.Cmd
37				b.spinner, cmd = b.spinner.Update(msg)
38				if b.state == browserStateTags && len(b.scanningTags) > 0 {
39					b.tagScanSpinnerIdx++
40					b.rebuildTagTable()
41				}
42				return b, cmd
43			}
44			return b, nil
45		}
46		return b.delegateUpdate(msg)
47	}
48	
49	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
50		if b.state == browserStateInput && b.focusedField == brFieldRepo {
51			var cmd tea.Cmd
52			b.repoInput, cmd = b.repoInput.Update(msg)
53			return b, cmd
54		}
55		if b.state == browserStateTags {
56			if b.filterActive {
57				var cmd tea.Cmd
58				b.filterInput, cmd = b.filterInput.Update(msg)
59				b.rebuildTagTable()
60				return b, cmd
61			}
62			var cmd tea.Cmd
63			b.tagTable, cmd = b.tagTable.Update(msg)
64			return b, cmd
65		}
66		return b, nil
67	}
68	
69	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
70		switch b.state {
71		case browserStateResolving:
72			return b, nil
73		case browserStateInput:
74			return b.handleInputKeyMsg(msg)
75		case browserStateTags:
76			return b.handleTagsKeyMsg(msg)
77		case browserStateStatus:
78			return b, nil
79		}
80		return b, nil
81	}
82	
83	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
84		switch msg.String() {
85		case "esc":
86			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
87		case "down":
88			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
89			b.updateFocus()
90			return b, nil
91		case "up":
92			b.focusedField = max(b.focusedField-1, brFieldRepo)
93			b.updateFocus()
94			return b, nil
95		case " ":
96			if b.focusedField >= 1 && b.focusedField <= len(b.entries) {
97				url := b.entries[b.focusedField-1].URL
98				b.selectedRegs[url] = !b.selectedRegs[url]
99				return b, nil
100			}
101		case "enter":
102			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
103				return b.submitSearch()
104			}
105			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
