14	// The search form and the results table, driven through the model — the router
15	// is what forwards keys to the browser, and the model is what wires the scan
16	// cache in. registry_browser_test.go covers opening, group resolution and the
17	// arrival of results; this file covers what the user does once it is open.
18	
19	// groupedModel returns a browser whose first registry resolved into a group of
20	// two members, so the entry list mixes members and a plain registry.
21	func groupedModel(t *testing.T) Model {
22		t.Helper()
23		m := feed(t, loadedModel(t), RegistryGroupCacheLoadedMsg{Entries: groupCacheFixture()})
24		return feed(t, m, testutil.Key("b"))
25	}
26	
27	func typeInto(t *testing.T, m Model, s string) Model {
28		t.Helper()
29		return feed(t, m, testutil.Type(s)...)
30	}
31	
32	// resultsModel returns a browser on its results screen, having actually
33	// submitted a search. searchedModel feeds tags in without submitting, which is
34	// enough to test where results land but leaves the browser on the form — the
35	// results table is only rebuilt while the tags screen is showing.
36	func resultsModel(t *testing.T, msgs ...tea.Msg) Model {
37		t.Helper()
38	
39		m := typeInto(t, browsingModel(t), "api")
40		m = feed(t, m, testutil.Key("enter"))
41		if m.registryBrowser.state != browserStateTags {
42			t.Fatalf("the search did not reach the results screen (state %d)", m.registryBrowser.state)
43		}
44		if len(msgs) == 0 {
45			msgs = []tea.Msg{
46				MultiRegistryTagsLoadedMsg{RegistryURL: "registry.example.com", Alias: "prod", Repo: "api", Tags: []string{"v1", "v2"}},
47				MultiRegistryTagsLoadedMsg{RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
48			}
49		}
50		return feed(t, m, msgs...)
51	}
52	
53	// ── The search form ──────────────────────────────────────────────────────────
54	
55	// Rule 135: ↑ / ↓ walk the fields. They clamp rather than wrap here, so the
56	// list of registries can be walked without the focus jumping past its ends.
57	func TestTheFormWalksFromTheRepoThroughEveryRegistryToTheButton(t *testing.T) {
58		m := browsingModel(t)
59		b := m.registryBrowser
60	
61		if b.focusedField != brFieldRepo {
62			t.Fatalf("the form opened on field %d, want the repository", b.focusedField)
63		}
64		m = feed(t, m, testutil.Key("up"))
65		if b.focusedField != brFieldRepo {
66			t.Errorf("focus = %d, want it held on the first field", b.focusedField)
67		}
68	
69		for i := range b.entries {
70			m = feed(t, m, testutil.Key("down"))
71			if b.focusedField != b.brFieldReg(i) {
72				t.Fatalf("focus = %d, want the checkbox for entry %d", b.focusedField, i)
73			}
74		}
75		m = feed(t, m, testutil.Key("down"))
76		if b.focusedField != b.brFieldSubmit() {
77			t.Errorf("focus = %d, want the button", b.focusedField)
78		}
79		feed(t, m, testutil.Key("down"))
80		if b.focusedField != b.brFieldSubmit() {
81			t.Errorf("focus = %d, want it held on the button", b.focusedField)
82		}
83	}
84	
85	// Every registry starts checked: the common case is searching all of them, and
86	// an empty selection would make the button do nothing on open.
87	func TestEveryRegistryStartsSelected(t *testing.T) {
88		b := browsingModel(t).registryBrowser
89	
90		for _, entry := range b.entries {
91			if !b.selectedRegs[entry.URL] {
92				t.Errorf("%s opened unchecked", entry.URL)
93			}
94		}
95	}
